def transform(binary):
 a=np.array([[int(x) for x in row] for row in binary],int);h,w=a.shape
 labels=np.full((h,w),-1,int);zcomps=[]
 for y in range(h):
  for x in range(w):
   if a[y,x]==0 and labels[y,x]<0:
    k=len(zcomps); q=deque([(y,x)]);labels[y,x]=k;pts=[]
    while q:
     yy,xx=q.popleft();pts.append((yy,xx))
     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<h and 0<=nx<w and a[ny,nx]==0 and labels[ny,nx]<0:
       labels[ny,nx]=k;q.append((ny,nx))
    zcomps.append(pts)
 internal=[k for k,p in enumerate(zcomps) if not any(y in (0,h-1) or x in (0,w-1) for y,x in p)]
 # mask interior edges
 b=a.copy()
 for k in internal:
  for y,x in zcomps[k]:
   if any(0<=y+dy<h and 0<=x+dx<w and a[y+dy,x+dx]==1 for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx): b[y,x]=3
 # find 1 comp labels
 ones=np.full((h,w),-1,int);ocs=[]
 for y in range(h):
  for x in range(w):
   if a[y,x]==1 and ones[y,x]<0:
    k=len(ocs);q=deque([(y,x)]);ones[y,x]=k;pts=[]
    while q:
     yy,xx=q.popleft();pts.append((yy,xx))
     for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<h and 0<=nx<w and a[ny,nx]==1 and ones[ny,nx]<0:ones[ny,nx]=k;q.append((ny,nx))
    ocs.append(pts)
 active=set()
 for k in internal:
  for y,x in zcomps[k]:
   for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
    ny,nx=y+dy,x+dx
    if 0<=ny<h and 0<=nx<w and a[ny,nx]==1: active.add(ones[ny,nx])
 for k in active:
  for y,x in ocs[k]:
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=y+dy,x+dx
     if 0<=ny<h and 0<=nx<w and a[ny,nx]==0 and labels[ny,nx] not in internal: b[ny,nx]=2
 return b,internal,active
